/**
 * Six-digit Unicode code points are legal in IRI query components. Their N-Quads UCHAR representation must still
 * contain exactly eight hexadecimal digits after the uppercase U.
 */
public class NQuadsWriterSupplementaryIriTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@TestFactory
	Collection<DynamicTest> supplementaryQueryIris() {
		List<DynamicTest> tests = new ArrayList<>();
		addTests(tests, 0x100000, "\\U00100000");
		addTests(tests, 0x10FFFD, "\\U0010FFFD");
		return tests;
	}

	private static void addTests(List<DynamicTest> tests, int codePoint, String escape) {
		String prefix = "http://example.org/resource?value=";
		IRI iri = VF.createIRI(prefix + new String(Character.toChars(codePoint)));
		Statement statement = VF.createStatement(iri, VF.createIRI("urn:p"), VF.createIRI("urn:o"));
		String expected = "<" + prefix + escape + "> <urn:p> <urn:o> .\n";
		for (boolean useOutputStream : new boolean[] { true, false }) {
			String name = "U+" + Integer.toHexString(codePoint).toUpperCase(java.util.Locale.ROOT)
					+ (useOutputStream ? " OutputStream" : " Writer");
			tests.add(dynamicTest(name + " exact escape", () -> {
				assertEquals(expected, serialize(statement, useOutputStream));
			}));
			tests.add(dynamicTest(name + " round trip", () -> {
				List<Statement> parsed = new ArrayList<>();
				NQuadsParser parser = new NQuadsParser();
				parser.setRDFHandler(new StatementCollector(parsed));
				parser.parse(new StringReader(serialize(statement, useOutputStream)), "");
				assertEquals(List.of(statement), parsed);
			}));
		}
	}

	private static String serialize(Statement statement, boolean useOutputStream) {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		StringWriter characters = new StringWriter();
		NQuadsWriter writer = useOutputStream ? new NQuadsWriter(bytes) : new NQuadsWriter(characters);
		writer.getWriterConfig()
				.set(BasicWriterSettings.RDF_OUTPUT_VERSION, VersionLabel.RDF_1_2_FULL)
				.set(BasicWriterSettings.CONVERT_RDF_12_REIFICATION, false)
				.set(NTriplesWriterSettings.ESCAPE_UNICODE, true);
		writer.startRDF();
		writer.handleStatement(statement);
		writer.endRDF();
		return useOutputStream ? bytes.toString(StandardCharsets.UTF_8) : characters.toString();
	}
}
